output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in one-cell-wide shelf aisles, which are pedestrian-only spaces.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not push a cart into a pedestrian-only single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "single_file_entry_requires_shopping",
    "text": "Entering a pedestrian-only shelf aisle on foot is permitted only when the shopper will pick an item there.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "selectFromSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "selectFromSingleFileAisle"
    }
  },
  {
    "id": "retrieve_cart_after_pedestrian_aisle_pickup",
    "text": "After selecting an item from a pedestrian-only shelf aisle, the shopper must return to and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "selectFromSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtAisleMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "upperAisleMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "selectFromSingleFileAisle",
      "discharge": "retrieveCartAtAisleMouth"
    }
  },
  {
    "id": "cart_abandonment_only_at_transfer_points",
    "text": "A cart may be left behind only at the entrance cart area, at a designated pedestrian-aisle transfer point, or while the shopper is inside the pedestrian aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartlessAllowedPlace": {
          "or": [
            "singleFileShelfAisle",
            "upperAisleMouth",
            "entranceCartArea"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedPlace"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_cart_before_shopping",
    "text": "Every shopper is obliged to take a cart before continuing through the store.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        }
      },
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              "entranceCartArea",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Shoppers must not leave the supermarket without their cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_westbound_travel",
    "text": "The store has one-way circulation, so westbound movement is prohibited.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "moveWest": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "moveWest"
    }
  }
]
